@ti.kernel
def apply_all_experts(tv: ti.template(), combined_forces: ti.template(), dt: ti.f32):
    for i in range(tv.pn):
        if tv.p.field[i].active > 0:
            combined_forces[i] = ti.Vector([0.0, 0.0])

            # Apply expert gravity
            if tv.p.field[i].active > 0:
                force = expert_gravity(ti.Field(i), i)
                combined_forces[i] += force * dt

            # Apply expert drift right
            if tv.p.field[i].active > 0:
                force = expert_drift_right(ti.Field(i), i)
                combined_forces[i] += force * dt * 0.8

            # Apply expert moving upwards
            if tv.p.field[i].active > 0:
                force = expert_moving_upwards(ti.Field(i), i)
                combined_forces[i] += force * dt * 0.8

            # Apply forces to velocity and apply damping
            tv.p.field[i].vel = combined_forces[i]
            tv.p.field[i].vel *= 0.98

            # Update position
            tv.p.field[i].pos[None] += tv.p.field[i].vel * dt
